select '4516575f-6f93-5c7b-aca2-6ab8f785bd7b', 'faq', false, '{"items": [{"question": "When is the cut-off point?", "answer": "You can sign up any time during the six weeks. We recommend starting within the first two weeks."}, {"question": "Do I need to paint a Warhammer model?", "answer": "No — any brand/range is fine if purchased via Guf Werribee and follows restrictions."}, {"question": "Is there a minimum spend?", "answer": "No minimum spend required."}, {"question": "Is there a minimum painting standard?", "answer": "No enforcement, but we recommend the \"Strict\" standard: at least three colours, painted base."}, {"question": "Do I have to paint purple?", "answer": "No — no theme colours required."}, {"question": "What if the model doesn''t come with a base?", "answer": "It must still fit within a 65mm footprint. Contact TOs if unsure."}, {"question": "Can I mount my model on an alternative base?", "answer": "Yes, but the base must match the intended size of the supplied base."}, {"question": "What happens if I don''t follow guidelines?", "answer": "Your piece won''t be eligible for prizes. Check with TOs if unsure."}, {"question": "Can I buy a kit with multiple models and enter one?", "answer": "Yes — you may enter a single model from a multi-kit box, but customization must use only parts from that model."}, {"question": "Can I use bits from other kits for basing?", "answer": "No — only tufts/flock/basing materials allowed. Exception: plastic basing kits (Citadel Skulls/Vines) are fine."}, {"question": "What are judges looking for?", "answer": "Each judge has their own criteria. For tips, see Mindful Painting Tips."}]}'::jsonb
