select '955e8eb5-e164-5e4e-b291-bddd35d6be90', 'faq', false, '{"items": [{"question": "What if my opponent cancels/we can''t get a game in?", "answer": "If one player is at fault for a cancelled game they will take a game loss with 0 points. The other player will be awarded a win as if they had 66 points. If you can''t schedule a game in and it''s neither player''s fault, you can agree to a draw with 33 to 33 points."}, {"question": "Can I change my list between rounds?", "answer": "No! Unless something big like a dataslate or new mission pack drops we''ll keep things the same. Your 1000 point and 2000 points lists will be able to be completely different though. They don''t even have to share the same super faction."}, {"question": "How are we handling terrain?", "answer": "I would recommend you talk to your opponent about that and set things up as you see fit. We encourage though that you use the WTC layouts (https://worldteamchampionship.com/wp-content/uploads/2025/03/WTC-2025-Map-Pack-Lite-v1.2compressed.pdf) and treat your bottom floor windows as blocking LOS. I''ve made some terrain footprint mats out of clear plastic and added them to various terrain sets at Guf Werribee to help facilitate this."}, {"question": "How are standings handled?", "answer": "Your standings will primarily be based on W/L/D record. The next tie breaker will be point differentials (how much you beat your opponent by, so make sure to deny those last minute primary points). Then if needed strength of schedule is used. Essentially, you''ll be rated slightly higher based on how strong your opponents were."}, {"question": "Is this a narrative event?", "answer": "No. I''m sure we''ll forge our own narratives through this, and tell some fun stories, but there is no narrative or crusade elements to this league. At its core, it''s just straight up matched play. I''m sure I''ll write some fun fluff about the Chaeos Cult but doing the same for your army is not a requirement nor an expectation."}]}'::jsonb
where exists (select 1 from public.battlepacks where id = '955e8eb5-e164-5e4e-b291-bddd35d6be90')
on conflict (pack_id, category_key) do nothing;
insert into public.battlepack_categories (pack_id, category_key, hidden, content)
select '955e8eb5-e164-5e4e-b291-bddd35d6be90', 'tickets', false, '{"body": "Tickets were $40 per player.", "url": null}'::jsonb
where exists (select 1 from public.battlepacks where id = '955e8eb5-e164-5e4e-b291-bddd35d6be90')
